from collections import Counter, defaultdict
from functools import lru_cache
from itertools import combinations
from pathlib import Path
import csv
import hashlib
import json
import re

from vs import corpus, dsl, ivtff

data = Path("data/raw")

@lru_cache
def pages(transliteration="zl"):
    return tuple(ivtff.parse(data / corpus.TRANSLITERATIONS[transliteration]))

corpus.pages = pages
map_leaf = defaultdict(set)
for page in pages():
    leaf = re.fullmatch(r"(f\d+)[rv]\d*", page.id)[1]
    map_leaf[leaf].add((page.meta.get("Q"), page.meta.get("B")))
assert all(len(x)==1 and None not in next(iter(x)) for x in map_leaf.values())
physical = {k: next(iter(v)) for k, v in map_leaf.items()}
mapped_faces = defaultdict(list)
for page in pages():
    leaf = re.fullmatch(r"(f\d+)[rv]\d*", page.id)[1]
    if re.fullmatch(r"f\d+[rv]\d+",page.id):
        mapped_faces[leaf].append(page.id)
archives = Path(__file__).parent/"bifolio_mapping_comparison.csv"
if archives.exists():
    pairs = defaultdict(set)
    for leaf, idx in physical.items():
        pairs[idx].add(leaf)
    actual_pairs = {(key[0], frozenset(leaves)) for key, leaves in pairs.items() if len(leaves)==2}
    with archives.open() as f:
        events = {(a, frozenset("f"+v for v in b.split("-"))) for r in csv.DictReader(f)
                  if r["in_evt"]=="True" for a,b in [r["pair"].split(":")]}
    print("MAP", len(physical), len(actual_pairs), len(events), len(actual_pairs&events),
          hashlib.sha256(archives.read_bytes()).hexdigest())

result={}
for tr in corpus.EVA_TRANSLITERATIONS:
    translation={}
    for split, ps in zip(("train","eval"), corpus.split_pages("practice",tr), strict=True):
        out=defaultdict(lambda: defaultdict(Counter))
        for t in dsl.select(dsl.tokens(ps), {"unit":["P"],"certain":True}):
            if t["language"] in {"A","B"}:
                out[(t["hand"],t["section"])][t["language"]][t["folio"]]+=1
        fields={}
        count_same=[]
        for (hand,section), groups in sorted(out.items()):
            cnt={l:dict(groups[l]) for l in ("A","B")}
            sides={k:sorted(v) for k,v in cnt.items()}
            leaves={l:sorted({re.match(r"f\d+",p)[0] for p in pp}) for l,pp in sides.items()}
            bifolia={l:sorted({":".join(physical[p]) for p in ll}) for l,ll in leaves.items()}
            quires={l:sorted({physical[p][0] for p in ll}) for l,ll in leaves.items()}
            fields[f"{hand}:{section}"]={l:{
                "pages":sides[l],"n_tokens":sum(cnt[l].values()),
                "leaves":leaves[l],"bifolia":bifolia[l],"quires":quires[l]
            } for l in ("A","B")}
            if all(cnt.values()):
                count_same.append({
                    "cell":[hand,section],"group":fields[f"{hand}:{section}"],
                    "shared_leaf":sorted(set(leaves["A"])&set(leaves["B"])),
                    "shared_bifolio":sorted(set(bifolia["A"])&set(bifolia["B"])),
                    "shared_quire":sorted(set(quires["A"])&set(quires["B"])),
                })
        translation[split]={"matched":count_same,"fields":fields}
        print(tr,split,len(ps),"cells",len(out),"matched",json.dumps(count_same))
    result[tr]=translation
(Path(__file__).parent/"support.json").write_text(json.dumps({"inventories":result,"panel_mapping":{
    leaf:{"pages":faces,"physical_bifolium":physical[leaf]} for leaf,faces in mapped_faces.items()
}}, indent=2)+"\n")

