from collections import Counter, defaultdict
from dataclasses import replace
from pathlib import Path
import json
import re

from vs import corpus, dsl, ivtff, path

PUBLISHED = (("chedy", "chody"), ("chedar", "chodar"),
             ("chedal", "chodal"), ("qokeedy", "qokeody"))
SITE = re.compile(r"[eo]d")
FOLIO = re.compile(r"f(\d+)[rv]\d*")
WORK = Path(__file__).resolve().parent


def physical_index():
    physical = {}
    for page in corpus.pages("zl"):
        leaf = FOLIO.fullmatch(page.id)
        if not leaf:
            raise ValueError(f"unrecognized physical leaf: {page.id}")
        physical[page.id] = {
            "leaf": int(leaf[1]), "quire": page.meta.get("Q"),
            "bifolium": f'{page.meta.get("Q")}:{page.meta.get("B")}',
        }
    return physical


def one_site_families(tokens):
    vocabulary = {t["w"] for t in tokens}
    families = []
    for word in sorted(vocabulary):
        sites = list(SITE.finditer(word))
        if len(sites) != 1 or sites[0][0] != "ed":
            continue
        slot = sites[0].start()
        other = word[:slot] + "o" + word[slot + 1:]
        if other in vocabulary:
            families.append((word, other))
    assert len({word for pair in families for word in pair}) == 2 * len(families)
    return families


def inventory(tokens, by_page):
    distinct = {t["folio"] for t in tokens}
    return {
        "pages": sorted(distinct),
        **{key: sorted({by_page[page][key] for page in distinct})
           for key in ("leaf", "bifolium", "quire")},
    }


def rate(numerator, denominator):
    return numerator / denominator if denominator else None


def summaries(tokens, observed_count, families):
    words = Counter(t["w"] for t in tokens)
    hits = {sequence: sum(count for word, count in words.items() if sequence in word)
            for sequence in ("ed", "od")}
    known = {side: sum(words[pair[i]] for pair in families)
             for i, side in enumerate(("ed", "od"))}
    return {
        "paragraph_tokens": observed_count,
        "certain_tokens": len(tokens),
        "omitted_fraction": rate(observed_count - len(tokens), observed_count),
        "literal_hits": hits,
        "literal_rates": {side: rate(count, len(tokens)) for side, count in hits.items()},
        "literal_ed_share_among_hits": rate(hits["ed"], hits["ed"] + hits["od"]),
        "one_site_tokens": known,
        "one_site_ed_share": rate(known["ed"], known["ed"] + known["od"]),
        "one_site_supported_types": sum(words[a] + words[b] > 0 for a, b in families),
        "published_forms": {word: words[word] for pair in PUBLISHED for word in pair},
    }


def stratified_match(tokens, all_tokens, families, physical):
    parts = defaultdict(lambda: {"A": [], "B": []})
    raw_counts = Counter((t["section"], t["hand"], t["language"]) for t in all_tokens)
    for t in tokens:
        parts[t["section"], t["hand"]][t["language"]].append(t)
    out = {}
    for (section, hand), pair in sorted(parts.items(), key=lambda entry: str(entry[0])):
        if not (pair["A"] and pair["B"] and section and hand != "None"):
            continue
        inv = {side: inventory(side_words, physical) for side, side_words in pair.items()}
        shared = {key: sorted(set(inv["A"][key]) & set(inv["B"][key]))
                  for key in ("leaf", "bifolium", "quire")}
        groups = {
            side: {**inv[side], **summaries(pair[side], raw_counts[section, hand, side], families)}
            for side in ("A", "B")
        }
        maybe_pairs = {(physical[a]["bifolium"], physical[a]["leaf"], physical[b]["leaf"])
                       for a in inv["A"]["pages"] for b in inv["B"]["pages"]
                       if physical[a]["bifolium"] == physical[b]["bifolium"]
                       and physical[a]["leaf"] != physical[b]["leaf"]}
        counts_a = Counter(t["w"] for t in pair["A"])
        counts_b = Counter(t["w"] for t in pair["B"])
        pair_table = [[ed, od, counts_a[ed], counts_a[od], counts_b[ed], counts_b[od]]
                      for ed, od in families
                      if counts_a[ed] + counts_a[od] + counts_b[ed] + counts_b[od] > 0]
        out[f"{section}:{hand}"] = {
            "family_count_fields": ["ED form", "OD form", "A ED", "A OD", "B ED", "B OD"],
            "family_counts": pair_table,
            "families_with_tokens_on_both_arms": sum(a + b > 0 and c + d > 0
                                                     for _, _, a, b, c, d in pair_table),
            "groups": groups,
            "shared": shared,
            "same_sheet_cross_leaf": sorted(maybe_pairs),
            "matched_spelling_loci_A": [
                {"locus": t["lid"], "position_one_based": t["k"] + 1,
                 "word": t["w"], "line_token_count": t["n"]}
                for t in pair["A"] if "ed" in t["w"]
            ],
        }
    return out


def pooled_deletions(tokens, families, physical):
    words_by_side = defaultdict(Counter)
    for token in tokens:
        words_by_side[token["language"]][token["w"]] += 1
    in_family = {word: i for pair in families for i, word in enumerate(pair)}
    def vector(words):
        counts = [0, 0, 0, 0]
        for word, n in words.items():
            counts[0] += n
            counts[1] += int("ed" in word) * n
            if word in in_family:
                counts[2 + in_family[word]] += n
        return counts

    def differences(values):
        a, b = values["A"], values["B"]
        result = []
        for n_a, d_a, n_b, d_b in [(a[1], a[0], b[1], b[0]),
                                   (a[2], a[2] + a[3], b[2], b[2] + b[3])]:
            result.append(n_b / d_b - n_a / d_a if d_a and d_b else None)
        return result

    all_vectors = {side: vector(words_by_side[side]) for side in ("A", "B")}
    result = {"pooled_differences": differences(all_vectors)}
    for scope in ("bifolium", "quire"):
        removed = defaultdict(Counter)
        for t in tokens:
            removed[physical[t["folio"]][scope], t["language"]][t["w"]] += 1
        out = {}
        for group in sorted({key[0] for key in removed}):
            keep = {side: [n - d for n, d in zip(all_vectors[side], vector(removed[group, side]))]
                    for side in ("A", "B")}
            out[group] = differences(keep)
        result[scope] = out
    return result


def collect(pages, physical, families):
    all_tokens = [t for t in dsl.tokens(pages) if t["unit"] == "P" and t["language"] in ("A", "B")]
    certain = [t for t in all_tokens if not ivtff.uncertain(t["w"])]
    groups = {}
    for side in ("A", "B"):
        words = [t for t in certain if t["language"] == side]
        raw_count = sum(t["language"] == side for t in all_tokens)
        groups[side] = {**inventory(words, physical), **summaries(words, raw_count, families)}
    return {
        "pooled": groups,
        "matched": stratified_match(certain, all_tokens, families, physical),
        "pooled_deletions": pooled_deletions(certain, families, physical),
    }


def main():
    physical = physical_index()
    output = {}
    for trans in corpus.EVA_TRANSLITERATIONS:
        training, evaluation = corpus.split_pages("practice", trans)
        families = one_site_families([t for t in dsl.select(dsl.tokens(training), {"unit": ["P"], "certain": True})
                                     if t["language"] in ("A", "B")])
        joined = {p.id: p for p in ivtff.parse(path("data", "raw", corpus.TRANSLITERATIONS[trans]),
                                              uncertain_space="join")}
        output[trans] = {"pairs": families}
        for name, pages in (("training", training), ("practice", evaluation)):
            output[trans][name] = {
                "split_uncertain_space": collect(pages, physical, families),
                "join_uncertain_space": collect([joined[p.id] for p in pages], physical, families),
            }
        training_match = output[trans]["training"]["split_uncertain_space"]["matched"]["S:3"]
        practice_match = output[trans]["practice"]["split_uncertain_space"]["matched"]["S:3"]
        for side in ("A", "B"):
            known_leaves = set(training_match["groups"][side]["leaf"])
            retained = [folio for folio in practice_match["groups"][side]["pages"]
                        if physical[folio]["leaf"] not in known_leaves]
            practice_match["groups"][side]["new_physical_eval_pages"] = retained

        mixed_hand = next(p for p in training if p.id == "f115r")
        documented_part = replace(mixed_hand, meta={**mixed_hand.meta, "H": "3"},
                                  lines=[line for line in mixed_hand.lines if line.n > 12])
        augmented = [documented_part if p.id == "f115r" else p for p in training]
        sensitivity = collect(augmented, physical, families)["matched"]["S:3"]["groups"]["B"]
        output[trans]["f115r_later_lines_B_sensitivity"] = sensitivity
    (WORK / "lexical-results.json").write_text(json.dumps(output, indent=2) + "\n")


if __name__ == "__main__":
    main()
